<?php get_header(); ?><section class="page-intro"><div class="container"><p class="eyebrow">Search</p><h1><?php printf(esc_html__('Results for: %s','circlepress'),'<span>'.esc_html(get_search_query()).'</span>'); ?></h1></div></section><div class="container archive-layout"><div><div class="archive-grid"><?php if(have_posts()):while(have_posts()):the_post(); ?><article class="post-card"><a class="post-thumb" href="<?php the_permalink(); ?>"><?php circlepress_post_image(); ?></a><span class="post-category">Kitchen notes</span><h2 class="post-title"><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p class="post-excerpt"><?php echo esc_html(circlepress_clean_excerpt( null, 20 )); ?></p></article><?php endwhile;else:?><div class="no-results"><h2>No recipes found.</h2><p>Try another search term or explore the categories.</p></div><?php endif; ?></div><div class="pagination"><?php echo paginate_links(array('type'=>'plain')); ?></div></div><aside class="sidebar"><h3>Search again</h3><?php get_search_form(); ?></aside></div><?php get_footer(); ?>
